import React from 'react';

export const themes = {
  default: { name: 'الافتراضي (بنفسجي)', gradient: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: '#667eea' },
  blue: { name: 'أزرق محيطي', gradient: 'linear-gradient(135deg, #0d6efd 0%, #0a58ca 100%)', color: '#0d6efd' },
  green: { name: 'أخضر طبيعي', gradient: 'linear-gradient(135deg, #198754 0%, #146c43 100%)', color: '#198754' },
  red: { name: 'أحمر ناري', gradient: 'linear-gradient(135deg, #dc3545 0%, #b02a37 100%)', color: '#dc3545' },
  orange: { name: 'برتقالي دافئ', gradient: 'linear-gradient(135deg, #fd7e14 0%, #ca6510 100%)', color: '#fd7e14' },
  teal: { name: 'فيروزي', gradient: 'linear-gradient(135deg, #20c997 0%, #198754 100%)', color: '#20c997' },
  gold: { name: 'ذهبي فاخر', gradient: 'linear-gradient(135deg, #d4af37 0%, #c5a028 100%)', color: '#d4af37' },
  dark: { name: 'أسود ليلي', gradient: 'linear-gradient(135deg, #212529 0%, #000000 100%)', color: '#212529' },
};

export default function ThemeSettingsModal({ show, onClose, currentTheme, onThemeChange }) {
  if (!show) return null;

  return (
    <div className="modal fade show d-block" tabIndex="-1" style={{ background: 'rgba(0,0,0,0.5)', zIndex: 1070 }}>
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">🎨 تخصيص المظهر</h5>
            <button type="button" className="btn-close" onClick={onClose}></button>
          </div>
          <div className="modal-body">
            <p className="text-muted mb-3">اختر لون الثيم المفضل لديك للموقع:</p>
            <div className="row g-3">
              {Object.entries(themes).map(([key, theme]) => (
                <div key={key} className="col-6 col-md-4">
                  <div 
                    className={`card h-100 cursor-pointer ${currentTheme === key ? 'border-primary border-3' : ''}`}
                    style={{ cursor: 'pointer', transition: 'transform 0.2s' }}
                    onClick={() => onThemeChange(key)}
                    onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                    onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
                  >
                    <div className="card-body text-center p-3">
                      <div 
                        className="rounded-circle mx-auto mb-2 shadow-sm" 
                        style={{ width: 40, height: 40, background: theme.gradient }}
                      ></div>
                      <small className="fw-bold d-block text-dark" style={{fontSize: '0.8rem'}}>{theme.name}</small>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
